using System;using System.IO;using System.Drawing;using System.Linq;using System.Windows.Forms;using System.Collections.Generic;
sealed partial class WorkspaceWindow {
 void QuickAccessTest(){var checks=new List<string>();try{timer.Stop();var viewport=home.Controls.OfType<Panel>().Single();var content=viewport.Controls.OfType<FlowLayoutPanel>().Single();var grid=content.Controls.OfType<FlowLayoutPanel>().First();if(!grid.Controls.ContainsKey("pulseHome"))throw new Exception("Pulse card missing");var group=grid.Controls["homeQuickTools"];if(group==null)throw new Exception("Quick access missing");foreach(string name in new[]{"Capture","Board"}){var b=group.Controls["quick"+name] as Button;if(b==null||b.Width<80||b.Height<80||b.ContextMenuStrip.Items.Count!=4)throw new Exception("Quick tile or menu missing");var info=QuickStartInfo(name,name=="Board"?"--new":"--video");if(!File.Exists(info.FileName)||info.UseShellExecute||String.IsNullOrWhiteSpace(info.Arguments))throw new Exception("Quick launcher path or action invalid");if(info.EnvironmentVariables.ContainsKey("JAGO_WORKSPACE_ROOT")||info.EnvironmentVariables.ContainsKey("JAGO_WORKSPACE_TAB_ROOT")||info.EnvironmentVariables.ContainsKey("JAGO_WORKSPACE_TAB_ID"))throw new Exception("Utility inherited a tab identity");}checks.Add("Capture and Board have keyboard-accessible tiles, action menus and independent launcher arguments");foreach(string theme in new[]{"Paper","Forest","Charcoal","Candy"}){ApplyAppearance(theme,false);foreach(var b in group.Controls.OfType<Button>())if(b.ForeColor!=ForeColor)throw new Exception("Theme mismatch");}checks.Add("Quick tile text and icons follow Workscape appearance");foreach(var size in new[]{new Size(1040,760),new Size(1480,980)}){ClientSize=size;viewport.AutoScrollPosition=Point.Empty;Application.DoEvents();foreach(Control card in grid.Controls)if(card.Bottom>grid.ClientSize.Height)throw new Exception("Home card clipped");var recovery=content.Controls.OfType<Button>().Single(b=>b.Text.StartsWith("Recover a previous"));viewport.AutoScrollPosition=new Point(0,Int32.MaxValue);Application.DoEvents();var box=viewport.RectangleToClient(recovery.RectangleToScreen(recovery.ClientRectangle));if(box.Bottom>viewport.ClientSize.Height)throw new Exception("Recovery clipped");viewport.AutoScrollPosition=Point.Empty;using(var capture=new Bitmap(Width,Height)){DrawToBitmap(capture,new Rectangle(0,0,Width,Height));capture.Save(Path.Combine(root,"home-"+size.Width+".png"));}}checks.Add("Pulse, utility tiles and recovery remain reachable at both window sizes");Atomic(Path.Combine(root,"result.json"),json.Serialize(new{ok=true,checks}));}catch(Exception e){Atomic(Path.Combine(root,"result.json"),json.Serialize(new{ok=false,error=e.ToString(),checks}));}allowClose=true;Close();}
}
